from base_sensor import BaseVirtualSensor


class LIS3DH_Simulator(BaseVirtualSensor):
    REG_WIDTH = 8

    def __init__(self):
        super().__init__()
        self.regs = {
            0x0F: 0x33,  # WHO_AM_I
            0x1E: 0x10,  # CTRL_REG0
            0x1F: 0x00,  # TEMP_CFG_REG
            0x20: 0x07,  # CTRL_REG1
            0x23: 0x00,  # CTRL_REG4
            0x27: 0x00,  # STATUS_REG
            0x28: 0x00,  # OUT_X_L
            0x29: 0x00,  # OUT_X_H
            0x2A: 0x00,  # OUT_Y_L
            0x2B: 0x00,  # OUT_Y_H
            0x2C: 0x00,  # OUT_Z_L
            0x2D: 0x00,  # OUT_Z_H
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            return 0
        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            return
        if nbytes == 1:
            current_value = self.regs[addr]
            data = (current_value & 0xFF) | (data << 8)
        self.regs[addr] = data
